# Homebrew formula for the Engra CLI. Generated by packaging/release.py in the
# release workflow; do not hand-edit. Release assets live in
# arenberg-engineering/engra-releases.
class Engra < Formula
  desc "AI coding agent and developer assistant for the terminal"
  homepage "https://engra.io"
  # Proprietary software of Arenberg AG, all rights reserved (LICENSE.txt).
  license :cannot_represent

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.2.2/engra-0.2.2-macos-arm64.tar.gz"
      sha256 "7fc01c25365421f746b01509e4014bd7dd478c95cc8c1487de399c69d60e0379"
    end
    on_intel do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.2.2/engra-0.2.2-macos-x64.tar.gz"
      sha256 "a1b99962ed7ecdc58a7c90ed9e4576ea33184d6e0ad90ff427c727bae20b5eca"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.2.2/engra-0.2.2-linux-arm64.tar.gz"
      sha256 "abb0e17a1acd0c63926c63c2298f8ba3c0d654a02073a05ec924382455600452"
    end
    on_intel do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.2.2/engra-0.2.2-linux-x64.tar.gz"
      sha256 "d36d5882968532b3fa004ec8aed9eb55ed32e4e25a35ee1c611354d3f09f4162"
    end
  end

  def install
    libexec.install "engra", "_internal"
    bin.install_symlink libexec/"engra"
    prefix.install "LICENSE.txt", "TERMS.md", "THIRD_PARTY_NOTICES.txt"
  end

  def caveats
    <<~EOS
      Sign in with:
        engra login

      Terms of Use: engra legal --terms

      Before uninstalling, run `engra logout` to remove saved credentials from
      the OS keychain. Settings and link state stay in ~/.config/engra (and
      doctor records in ~/.engra); remove them to clear everything.
    EOS
  end

  test do
    assert_equal "engra #{version}", shell_output("#{bin}/engra --version").strip
    assert_match "doctor", shell_output("#{bin}/engra --help")
    assert_match "Arenberg AG", shell_output("#{bin}/engra legal")
  end
end
